package main

import (
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

const wrapper = `#!/bin/sh
# Generated by ` + "`beckon install swiftbar`" + `. SwiftBar runs this every 3 s.
# <swiftbar.hideAbout>true</swiftbar.hideAbout>
# <swiftbar.hideRunInTerminal>true</swiftbar.hideRunInTerminal>
# <swiftbar.hideLastUpdated>true</swiftbar.hideLastUpdated>
# <swiftbar.hideDisablePlugin>true</swiftbar.hideDisablePlugin>
# <swiftbar.hideSwiftBar>true</swiftbar.hideSwiftBar>
export PATH="$HOME/.local/share/mise/shims:$HOME/go/bin:/opt/homebrew/bin:/usr/local/bin:$PATH"
exec beckon swiftbar "$@"
`

var groups = []struct{ state, title, color, icon string }{
	{"blocked", "Waiting for your input", "#f38ba8", "🔴"},
	{"idle", "Idle", "#a6e3a1", "🟢"},
	{"working", "Working", "#f9e2af", "🟡"},
}

// renderSwiftbar writes SwiftBar plugin output: the bar shows the count of the
// most urgent non-empty group, the menu lists agents; clicking runs `self focus`.
func renderSwiftbar(w io.Writer, agents []Agent, self string) {
	if len(agents) == 0 {
		fmt.Fprint(w, "●| color=#9399b2\n---\nNo agents\n")
		return
	}
	by := map[string][]Agent{}
	for _, a := range agents {
		by[a.State] = append(by[a.State], a)
	}
	for _, g := range groups {
		if n := len(by[g.state]); n > 0 {
			fmt.Fprintf(w, "%s %d| color=%s\n", g.icon, n, g.color)
			break
		}
	}
	for _, g := range groups {
		if len(by[g.state]) == 0 {
			continue
		}
		fmt.Fprintf(w, "---\n%s (%d)| size=11\n", g.title, len(by[g.state]))
		for _, a := range by[g.state] {
			fmt.Fprintf(w, "%s › %s  ·  %s| bash=%q param1=focus param2=%s param3=%d terminal=false\n",
				a.Project, a.Tab, a.Agent, self, a.Socket, a.ID)
		}
	}
	fmt.Fprint(w, "---\nRefresh| refresh=true\n")
}

func runSwiftbar(w io.Writer) {
	agents, err := listAgents()
	if err != nil {
		fmt.Fprintf(w, "●\n---\n%s| color=#f38ba8\n", err)
		return
	}
	self, _ := os.Executable()
	if r, err := filepath.EvalSymlinks(self); err == nil {
		self = r
	}
	renderSwiftbar(w, agents, self)
}

// swiftbarDir reads SwiftBar's plugin directory ("" if unset).
func swiftbarDir() string {
	out, err := exec.Command("defaults", "read", "com.ameba.SwiftBar", "PluginDirectory").Output()
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(out))
}

func installSwiftbar() error {
	dir := swiftbarDir()
	if dir == "" {
		home, _ := os.UserHomeDir()
		dir = filepath.Join(home, ".config/swiftbar")
		if err := exec.Command("defaults", "write", "com.ameba.SwiftBar", "PluginDirectory", dir).Run(); err != nil {
			return fmt.Errorf("set SwiftBar PluginDirectory: %w", err)
		}
		fmt.Println("set SwiftBar PluginDirectory to", dir)
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	p := filepath.Join(dir, "beckon.3s.sh")
	if err := os.WriteFile(p, []byte(wrapper), 0o755); err != nil {
		return err
	}
	fmt.Println("wrote", p)
	return nil
}
